    [Theory]
    [MemberData(nameof(OriginalRows))]
    public void Source_cold_leash_sensor_pulse_and_immediate_pylon_index_match(int family, int a, int b, int c,
        string gridHash, string metadataHash, string rngHash, int next)
    {
        var tiles = new WorldTileStore(new(80, 80)); var records = new List<WorldTileEntity>();
        if (family == 0)
        {
            tiles.Set(40, 40, new WorldTile { Type = (ushort)a, Flags = WorldTileFlags.Active });
            int kind = b == 1 ? (a == 723 ? 10 : 9) : b == 3 ? 6 : a == 723 ? 9 : 10;
            if (b != 2) records.Add(new(0, 40, 40, (WorldTileEntityKind)kind, kind == 6 ? new WorldItemTileEntityPayload(new((short)c, 0, (short)(c > 0 ? 3 : 0))) : new WorldLeashedAnchorPayload((short)c)));
        }
        else if (family == 1)
        {
            for (int x = 0; x < 3; x++) for (int y = 0; y < 4; y++) tiles.Set(40 + x, 40 + y, new WorldTile { Type = 597, Flags = WorldTileFlags.Active, FrameX = (short)(a * 54 + x * 18), FrameY = (short)(y * 18) });
            if (c == 0) for (int x = 0; x < 3; x++) tiles.Set(40 + x, 44, new WorldTile { Type = 1, Flags = WorldTileFlags.Active });
            if (b != 1) records.Add(new(0, 40, 40, b == 0 ? WorldTileEntityKind.TeleportationPylon : WorldTileEntityKind.FoodPlatter, b == 0 ? WorldEmptyTileEntityPayload.Instance : new WorldItemTileEntityPayload(new(353, 0, 3))));
            foreach (var extra in new[] { (id: 1, x: 60, style: 2), (id: 2, x: 64, style: 3) })
            {
                tiles.Set(extra.x, 60, new WorldTile { Type = 597, Flags = WorldTileFlags.Active, FrameX = (short)(extra.style * 54) });
                records.Add(new(extra.id, (short)extra.x, 60, WorldTileEntityKind.TeleportationPylon, WorldEmptyTileEntityPayload.Instance));
            }
        }
        else
        {
            tiles.Set(40, 40, new WorldTile { Type = 423, Flags = WorldTileFlags.Active, FrameX = (short)(b == 1 ? 18 : 0), FrameY = (short)(a * 18) });
            for (int x = 40; x <= 42; x++) { var t = tiles.Get(x, 40); t.Flags |= c switch { 1 => WorldTileFlags.WireRed, 2 => WorldTileFlags.WireBlue, 3 => WorldTileFlags.WireGreen, 4 => WorldTileFlags.WireYellow, _ => 0 }; tiles.Set(x, 40, in t); }
            var torch = tiles.Get(42, 40); torch.Type = 4; torch.Flags |= WorldTileFlags.Active; tiles.Set(42, 40, in torch);
            tiles.Set(42, 41, new WorldTile { Type = 1, Flags = WorldTileFlags.Active });
            records.Add(new(0, 40, 40, WorldTileEntityKind.LogicSensor, new WorldLogicSensorPayload((byte)a, b == 1)));
        }
        Assert.True(tiles.TryAttachTileEntities(records.ToArray(), 1000));
        var random = new FixtureRandom(1458); var frame = new GenerationTileFraming1458(tiles, random);
        if (family == 1) { tiles.RuntimeTileEntities!.RequestImmediatePylonUpdate(); frame.TileFrame(41, 42); var expected = new List<WorldPylonInfo1458>(); if (b == 0 && c == 0) expected.Add(new(40, 40, a)); expected.Add(new(60, 60, 2)); expected.Add(new(64, 60, 3)); Assert.Equal(expected, tiles.RuntimeTileEntities.CapturePylonSnapshot()); Assert.Equal(int.MaxValue, tiles.RuntimeTileEntities.PylonUpdateCooldown); if (b != 1) { var owner = tiles.RuntimeTileEntities; Assert.True(owner.TryPrepare(1, out var change)); Assert.NotNull(change); Assert.True(change.TryStageEmptyPlacement(70, 70, WorldTileEntityKind.DisplayDoll, out int created)); Assert.Equal(3, created); Assert.True(change.TrySeal()); WorldSectionId[] sections = [TerrariaSectionGeometry.FromTile(tiles.Dimensions, 70, 70)]; tiles.BeginMetadataMutation(sections); try { Assert.True(change.TryAdoptUnpublished()); } finally { tiles.EndMetadataMutation(sections); } Assert.Equal(expected, owner.CapturePylonSnapshot()); } }
        else { if (family == 2) frame.SourceWiringCircuit = new WorldWiringCircuit1458(tiles, new WorldWiringDeviceExecutor1458(tiles)); frame.KillTile(40, 40); }
        Assert.Equal(gridHash, GridDigest(tiles)); using var m = new MemoryStream(); Assert.Equal(WorldFileTileEntityEncodeResult.Encoded,
            WorldFileTileEntityEncoder.TryEncode(tiles.RuntimeTileEntities!.CaptureSnapshot(), new(80, 80), 1000, m, out _));
        Assert.Equal(metadataHash, Convert.ToHexString(SHA256.HashData(m.ToArray()))); Assert.Equal(rngHash, RngDigest(random.Source)); Assert.Equal(next, random.Next());
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    public void Unqualified_sensor_owner_or_component_is_refused_before_any_effect(int boundary)
    {
        var tiles = new WorldTileStore(new(80, 80));
        tiles.Set(40, 40, new WorldTile { Type = 423, Flags = WorldTileFlags.Active | WorldTileFlags.WireRed });
        tiles.Set(41, 40, new WorldTile { Type = (ushort)(boundary == 1 ? 33 : 4), Flags = WorldTileFlags.Active | WorldTileFlags.WireRed | (boundary == 2 ? WorldTileFlags.Actuator : 0) });
        Assert.True(tiles.TryAttachTileEntities([new(0, 40, 40, WorldTileEntityKind.LogicSensor, new WorldLogicSensorPayload(3, true))], 1000));
        var random = new FixtureRandom(1458); var frame = new GenerationTileFraming1458(tiles, random);
        if (boundary != 0) { var ownerTiles = boundary == 3 ? new WorldTileStore(new(80, 80)) : tiles; frame.SourceWiringCircuit = new WorldWiringCircuit1458(ownerTiles, new WorldWiringDeviceExecutor1458(ownerTiles)); }
        string grid = GridDigest(tiles), rng = RngDigest(random.Source); var before = tiles.RuntimeTileEntities!.CaptureSnapshot();
        Assert.Throws<NotSupportedException>(() => frame.KillTile(40, 40)); Assert.Equal(grid, GridDigest(tiles)); Assert.Equal(rng, RngDigest(random.Source)); Assert.Equal(before, tiles.RuntimeTileEntities.CaptureSnapshot());
    }

    private static string GridDigest(WorldTileStore tiles)
    {
        using var m = new MemoryStream(); using (var w = new BinaryWriter(m, Encoding.UTF8, true)) for (int x = 0; x < 80; x++) for (int y = 0; y < 80; y++)
        {
            var s = tiles.Get(x, y); w.Write(s.IsActive); w.Write(s.Type); w.Write(s.Wall); w.Write(s.FrameX); w.Write(s.FrameY);
            w.Write(s.LiquidAmount); w.Write((byte)s.LiquidKind); w.Write(s.IsHalfBrick); w.Write(s.SourceSlope); w.Write(s.TileColor); w.Write(s.WallColor);
            w.Write((s.Flags & WorldTileFlags.WireRed) != 0); w.Write((s.Flags & WorldTileFlags.WireBlue) != 0); w.Write((s.Flags & WorldTileFlags.WireGreen) != 0);
            w.Write((s.Flags & WorldTileFlags.WireYellow) != 0); w.Write(s.HasActuator); w.Write(s.IsActuated); w.Write(s.IsBlockInvisible);
            w.Write(s.IsBlockFullbright); w.Write(s.IsWallInvisible); w.Write(s.IsWallFullbright);
        }
        return Convert.ToHexString(SHA256.HashData(m.ToArray()));
    }
    private static string RngDigest(TerraRuntime.Core.VanillaUnifiedRandom1458 random)
    {
        const BindingFlags flags = BindingFlags.Instance | BindingFlags.NonPublic; using var m = new MemoryStream();
        using (var w = new BinaryWriter(m, Encoding.UTF8, true))
        {
            w.Write((uint)typeof(TerraRuntime.Core.VanillaUnifiedRandom1458).GetField("inext", flags)!.GetValue(random)!);
            foreach (int v in (int[])typeof(TerraRuntime.Core.VanillaUnifiedRandom1458).GetField("seedArray", flags)!.GetValue(random)!) w.Write(v);
        }
        return Convert.ToHexString(SHA256.HashData(m.ToArray()));
    }
    private sealed class FixtureRandom(int seed) : IWorldGenerationVanillaRandom
    {
        internal readonly TerraRuntime.Core.VanillaUnifiedRandom1458 Source = new(seed);
        public int Next() => Source.Next(); public int Next(int max) => Source.Next(max); public int Next(int min, int max) => Source.Next(min, max);
        public double NextDouble() => Source.NextDouble(); public void NextBytes(byte[] bytes) => Source.NextBytes(bytes);
    }
